package main
import("bytes";"encoding/csv";"encoding/json";"flag";"fmt";"net/http";"os";"strings";"sync";"sync/atomic";"time")
func main(){addr:=flag.String("addr","http://127.0.0.1:8080","base URL");clients:=flag.Int("clients",8,"concurrent workers");duration:=flag.Duration("duration",10*time.Second,"run duration");csvPath:=flag.String("csv","bench.csv","CSV output path");flag.Parse();base:=strings.TrimRight(*addr,"/");client:=&http.Client{Timeout:3*time.Second};var ops,fail atomic.Uint64;stop:=time.Now().Add(*duration);var wg sync.WaitGroup;lat:=make(chan time.Duration,100000);for w:=0;w<*clients;w++{wg.Add(1);go func(id int){defer wg.Done();i:=0;for time.Now().Before(stop){key:=fmt.Sprintf("bench:%d:%d",id,i);body,_:=json.Marshal(map[string]string{"key":key,"value":"value"});start:=time.Now();req,e:=http.NewRequest(http.MethodPut,base+"/api/kv",bytes.NewReader(body));if e==nil{req.Header.Set("Content-Type","application/json");var resp *http.Response;resp,e=client.Do(req);if e==nil{resp.Body.Close();if resp.StatusCode>=300{fail.Add(1)}}};lat<-time.Since(start);if e!=nil{fail.Add(1)};ops.Add(1);i++}}(w)};wg.Wait();close(lat);var total time.Duration;for d:=range lat{total+=d};elapsed:=*duration.Seconds();fmt.Printf("operations=%d failures=%d throughput_ops_sec=%.1f mean_latency_ms=%.3f\n",ops.Load(),fail.Load(),float64(ops.Load())/elapsed,float64(total.Microseconds())/1000/float64(max(ops.Load(),1)));f,e:=os.Create(*csvPath);if e!=nil{fmt.Fprintln(os.Stderr,e);os.Exit(1)};defer f.Close();w:=csv.NewWriter(f);_=w.Write([]string{"operations","failures","duration_seconds","throughput_ops_sec","mean_latency_ms"});_=w.Write([]string{fmt.Sprint(ops.Load()),fmt.Sprint(fail.Load()),fmt.Sprint(elapsed),fmt.Sprintf("%.2f",float64(ops.Load())/elapsed),fmt.Sprintf("%.3f",float64(total.Microseconds())/1000/float64(max(ops.Load(),1)))});w.Flush()}
